-- Inicio de sesión: equivalente en Postgres/Supabase de la migración EF "AddUsers".
-- AppUsers guarda el correo, el hash PBKDF2 de la contraseña (nunca la contraseña) y el id de su cuenta de Google.
-- Se activa RLS sin políticas, como en el resto de tablas, para que no sea accesible desde la API pública de Supabase.

create table if not exists "AppUsers" (
  "Id" integer generated by default as identity primary key,
  "Email" varchar(320) not null,
  "DisplayName" varchar(100) null,
  "PasswordHash" text null,
  "GoogleSubject" varchar(100) null,
  "CreatedAt" timestamp without time zone not null,
  "LastLoginAt" timestamp without time zone null
);
create unique index if not exists "IX_AppUsers_Email" on "AppUsers" ("Email");
create index if not exists "IX_AppUsers_GoogleSubject" on "AppUsers" ("GoogleSubject");

alter table "AppUsers" enable row level security;
